-- GENERATED by setup/build_pipeline_spec.py. Publishes silver -> existing gold tables.
-- Gold tables keep their identity (certification, domains, Genie, metric views).
-- Guard: never overwrite governed gold from an empty or mis-pathed landing zone.
SELECT assert_true((SELECT count(*) FROM fr_stable_catalog.supply_chain.silver_dim_launch) > 0 AND (SELECT count(*) FROM fr_stable_catalog.supply_chain.silver_fact_equipment_telemetry) > 0 AND (SELECT count(*) FROM fr_stable_catalog.supply_chain.silver_fact_demand_forecast) > 0, 'silver is empty: refusing to publish gold');

CREATE TABLE IF NOT EXISTS fr_stable_catalog.supply_chain.dim_routing (
  sku STRING COMMENT 'SKU.',
  primary_line STRING COMMENT 'Primary production line for this SKU.',
  plant STRING COMMENT 'Plant of the primary line.',
  process_step STRING COMMENT 'Process step on that line (e.g. coating, compression, packaging).'
) COMMENT 'Primary production routing: the main line (and plant/process step) where each SKU is made. Links a launch to the equipment that can put its supply at risk. Instradamento produttivo.';

INSERT OVERWRITE fr_stable_catalog.supply_chain.demo_config SELECT demo_date, history_start, forecast_end, predicted_failure_end, rng_seed FROM fr_stable_catalog.supply_chain.silver_demo_config;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_date SELECT date, month, quarter, day_of_week, is_weekend FROM fr_stable_catalog.supply_chain.silver_dim_date;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_dc SELECT dc, market FROM fr_stable_catalog.supply_chain.silver_dim_dc;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_equipment SELECT plant, line, equipment, equipment_class, criticality FROM fr_stable_catalog.supply_chain.silver_dim_equipment;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_launch SELECT launch_id, sku, cluster_bu, planned_launch_date, actual_launch_date, phase, master_data_ready_flag, artwork_ready_flag, serialization_ready_flag, launch_readiness_score FROM fr_stable_catalog.supply_chain.silver_dim_launch;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_line SELECT plant, line, process_step, criticality FROM fr_stable_catalog.supply_chain.silver_dim_line;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_market SELECT market, region FROM fr_stable_catalog.supply_chain.silver_dim_market;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_plant SELECT plant, site_type, city, country FROM fr_stable_catalog.supply_chain.silver_dim_plant;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_product SELECT sku, brand, therapeutic_area, form, pack_size, shelf_life_months, is_cold_chain, launch_phase, launch_date, cluster_bu, material_master_status, serialization_status, artwork_version, artwork_status FROM fr_stable_catalog.supply_chain.silver_dim_product;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_routing SELECT sku, primary_line, plant, process_step FROM fr_stable_catalog.supply_chain.silver_dim_routing;
INSERT OVERWRITE fr_stable_catalog.supply_chain.dim_supplier SELECT supplier, material_type, is_internal FROM fr_stable_catalog.supply_chain.silver_dim_supplier;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_batch SELECT batch_id, sku, line, plant, start_date, end_date, planned_qty, actual_qty, status, yield, rft_flag FROM fr_stable_catalog.supply_chain.silver_fact_batch;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_batch_genealogy SELECT finished_lot, intermediate_lot, api_lot, api_supplier, api_qty, intermediate_qty, finished_qty, api_yield, intermediate_yield FROM fr_stable_catalog.supply_chain.silver_fact_batch_genealogy;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_demand_forecast SELECT sku, brand, market, month, statistical_forecast, consensus_forecast, actual_sales FROM fr_stable_catalog.supply_chain.silver_fact_demand_forecast;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_deviation SELECT deviation_id, batch_id, severity, root_cause_category, capa_status, capa_due_date, capa_closed_date FROM fr_stable_catalog.supply_chain.silver_fact_deviation;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_equipment_telemetry SELECT date, equipment, vibration, temperature, motor_current, pressure, anomaly_score FROM fr_stable_catalog.supply_chain.silver_fact_equipment_telemetry;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_inventory SELECT date, sku, dc, on_hand_qty, in_transit_qty, safety_stock_qty, days_of_inventory, expiry_at_risk_qty FROM fr_stable_catalog.supply_chain.silver_fact_inventory;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_maintenance SELECT wo_id, equipment, start_date, end_date, downtime_min, maintenance_type, failure_mode, cost FROM fr_stable_catalog.supply_chain.silver_fact_maintenance;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_oee SELECT date, shift, line, planned_runtime_min, downtime_min, availability, performance, quality, oee FROM fr_stable_catalog.supply_chain.silver_fact_oee;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_qc_release SELECT batch_id, sku, plant, release_date, release_cycle_days, potency_pass, stability_pass, release_status FROM fr_stable_catalog.supply_chain.silver_fact_qc_release;
INSERT OVERWRITE fr_stable_catalog.supply_chain.fact_service SELECT month, sku, market, orders, otif, stockout_days, backorder_qty FROM fr_stable_catalog.supply_chain.silver_fact_service;
